Invoke-MgGraphRequest -Method GET -Uri ('https://graph.microsoft.com/beta/deviceManagement/deviceConfigurations/' + $created.id + '/assignments') -ErrorAction Stop | ConvertTo-Json -Depth 30
# Pass for a new candidate: no assignments. Never add an assignment as part of creation.

